except Exception as exc:
    print(json.dumps({'psutil_error': str(exc)})); raise
repo=Path('C:/Dev/AIpinho')
mods=[
 'aipinho',
 'aipinho.main',
 'aipinho.services.artifacts.file_container_signature_service',
 'aipinho.services.artifacts.media_candidate_identity_policy',
 'aipinho.services.artifacts.media_inventory_row_taxonomy_service',
