]
procs=[]
for p in psutil.process_iter(['pid','name','exe','cmdline','cwd','create_time']):
    try:
        cmd=' '.join(p.info.get('cmdline') or [])
        if 'uvicorn' in cmd and 'aipinho.main:app' in cmd and '9088' in cmd:
            conns=[]
            try:
                for c in p.net_connections(kind='inet'):
                    if c.status == psutil.CONN_LISTEN:
                        conns.append({'ip': c.laddr.ip, 'port': c.laddr.port})
            except Exception:
                pass
            procs.append({
                'pid': p.pid,
                'cwd': p.info.get('cwd'),
                'exe': p.info.get('exe'),
                'cmdline': p.info.get('cmdline'),
                'started_at': time.strftime('%Y-%m-%d %H:%M:%S %z', time.localtime(p.info.get('create_time'))),
                'listen': conns,
            })
    except Exception:
        pass
endpoints={}
for ep in ['version','runtime','modules','contracts']:
    try:
        r=subprocess.run([sys.executable,'-c',f"import urllib.request,json; r=urllib.request.urlopen('http://127.0.0.1:9088/api/v1/{ep}', timeout=10); print(r.status); print(r.read().decode('utf-8')[:1000])"],capture_output=True,text=True,timeout=15)
        endpoints['/api/v1/'+ep]={'returncode':r.returncode,'stdout':r.stdout,'stderr':r.stderr}
    except Exception as exc:
        endpoints['/api/v1/'+ep]={'error':str(exc)}
