 'ahead_behind': subprocess.check_output(['git','rev-list','--left-right','--count','origin/main...HEAD'],cwd=repo,text=True).strip(),
 'status_short': subprocess.check_output(['git','status','--short'],cwd=repo,text=True),
 'python_executable': sys.executable,
